public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("DataOutput can not be null");
    }
    int totalBytes = 0;
    LinkedBuffer cur = node;
    while (cur != null) {
        if (cur.buffer != null) {
            int len = Math.min(cur.pos, cur.buffer.length);
            out.write(cur.buffer, 0, len);
            totalBytes += len;
        }
        cur = cur.next;
    }
    return totalBytes;
}

