public static boolean arrayequals(byte[] a, byte[] b, int count) {
    // Quick checks for null references
    if (a == null || b == null) {
        return false;
    }

    // Handle count zero: zero bytes are always equal
    if (count == 0) {
        return true;
    }

    // Validate count bounds
    if (count < 0 || count > a.length || count > b.length) {
        throw new IllegalArgumentException("Count must be non-negative and not exceed array lengths");
    }

    // Compare the first 'count' bytes
    for (int i = 0; i < count; i++) {
        if (a[i] != b[i]) {
            return false;
        }
    }
    return true;
}

