    StringBuilder abbrev = new StringBuilder();
    boolean startOfToken = true;
    for (int i = 0; i < remaining.length(); i++) {
        char ch = remaining.charAt(i);
        if (ch == '.' || ch == '_' || ch == ' ') {
            startOfToken = true;
            continue;
